#toast-container > .toast {
    color: #FFFFFF !important;  
    background: rgba(187, 210, 238, 0.3) !important;   
    box-shadow: 0 4px 12px rgba(165, 200, 228, 0.3) !important; 
    padding: 7px 15px !important;
    border-radius: 10px !important;
    font-family: inherit !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    min-width: 100px !important;
    max-width: 50vw !important;
    text-align: center !important;
}

#toast-container > .toast::before {
    content: '' !important;
    position: absolute !important;
    left: 10px !important;
    top: 53% !important;
    transform: translateY(-50%) !important;
    width: 26px !important;
    height: 26px !important;
    background: url('https://i.postimg.cc/LX94xfbk/IMG-0447.png') center/contain no-repeat !important;
    filter: brightness(4) contrast(1.5) !important;
}

/* 成功弹窗 */
#toast-container > .toast-success::before {
    filter: hue-rotate(60deg) saturate(0.8) !important;
}

/* 错误弹窗 —— 可单独调大小、位置 */
#toast-container > .toast-error::before {
    background: url('https://i.postimg.cc/LX94xfbk/IMG-0447.png') center/contain no-repeat !important;
    width: 16px !important;     /* 错误图标宽度 */
    height: 16px !important;    /* 错误图标高度 */
    left: 14px !important;      /* 左右位置：数字变大往右，变小往左 */
    top: 50% !important;       /* 上下不变 */
}

/* 信息弹窗 */
#toast-container > .toast-info::before {
    filter: hue-rotate(180deg) saturate(0.8) !important;
}

/* 警告弹窗 —— 可单独调大小、位置 */
#toast-container > .toast-warning::before {
    background: url('https://i.postimg.cc/LX94xfbk/IMG-0447.png') center/contain no-repeat !important;
    width: 16px !important;     /* 警告图标宽度 */
    height: 16px !important;    /* 警告图标高度 */
    left: 14px !important;      /* 左右位置 */
    top: 50% !important;
}

#toast-container > .toast {
    padding-left: 45px !important; 
}

